// Full Bluetooth SIG assigned numbers: company IDs (Manufacturer Specific
// Data) and 16-bit service UUIDs (SIG member UUIDs and standard services).
// Generated by tools/gen-sig.mjs from the SIG's published registry and
// committed so the app works offline (~140 KB of JSON).
//
// companies.ts stays the curated first choice: it carries the short names
// and police-relevant notes; this is the fallback for everything else.

const DATA: {companies: Record<string, string>; services: Record<string, string>} = require('./sig-data.json');

export function sigCompany(id: number): string | undefined {
  return DATA.companies[String(id)];
}

/** 16-bit service UUID as 4 uppercase hex digits, e.g. "FEAA". */
export function sigService(uuid16: string): string | undefined {
  return DATA.services[uuid16.toUpperCase()];
}

export function sigCounts(): {companies: number; services: number} {
  return {companies: Object.keys(DATA.companies).length, services: Object.keys(DATA.services).length};
}
